require('dotenv').config({path:'.env.production',quiet:true});require('dotenv').config({path:'.env.development',quiet:true});
const m=require('mongoose'),crypto=require('crypto');
const emit=x=>console.log(JSON.stringify(x));
(async()=>{await m.connect(process.env.MONGO_URI);const d=m.connection.db;
const {fetchLiveNoteRows}=require('./dist/src/services/apx/apxPdfSigningService');
const {deriveApxAssetKey:key}=require('./dist/src/services/apx/apxAssetKey');
const {findOrCreatePdfByAssetKey}=require('./dist/src/services/apx/apxPdfAsset');
const Class=require('./dist/src/models/Class').default;
const Pdf=require('./dist/src/models/Pdf').default;
const rows=await fetchLiveNoteRows('49','472');const map=new Map(rows.map(r=>[r.classRowId,r]));const plan=[];
for(const t of targets){const row=map.get(t.sourceId);if(!row)throw Error('Source missing '+t.sourceId);const ak=key(row.noteRawLink);if(crypto.createHash('sha256').update(ak).digest('hex')!==t.pdfIdentityHash)throw Error('PDF drift '+t.sourceId);
const c=await Class.findById(t.classId).lean();if(!c||c.apxAssetKey!==key(row.videoLink,/youtube|youtu\.be/i.test(row.videoLink)))throw Error('Class identity mismatch '+t.sourceId);
const placement=await d.collection('courseclasses').findOne({course:new m.Types.ObjectId('6a455cd5ebb42f585d9ca997'),class:c._id,isActive:{$ne:false}});if(!placement)throw Error('Placement missing '+t.sourceId);
for(const f of ['mainCategory','category','section'])if(!c[f])throw Error('Taxonomy missing '+t.sourceId+' '+f);
plan.push({t,row,ak,c});}
emit({event:'preflight',count:plan.length,commit:process.argv.includes('--commit')});
if(!process.argv.includes('--commit')){await m.disconnect();return;}
const {loadDocumentStorageConfig}=require('./dist/src/config/documentStorage');const {createB2StorageAdapter}=require('./dist/src/services/documentStorage');const cfg=loadDocumentStorageConfig();const storage=createB2StorageAdapter(cfg);
let success=0,failed=0;
for(const {t,row,ak,c} of plan){try{
const result=await findOrCreatePdfByAssetKey({assetKey:ak,live:{id:row.classRowId,rawLink:row.noteRawLink,encrypted:row.encrypted,encryptionKey:row.encryptionKey,encryptionVersion:row.encryptionVersion},title:row.title.trim(),resolveTaxonomy:async()=>({mainCategory:c.mainCategory,category:c.category,section:c.section,topic:c.topic??null}),teacherName:c.teacherName},'472');
let p=await Pdf.findById(result.pdfId).lean();if(!p?.pdfAsset?.key){const {signPdfLink}=require('./dist/src/services/apx/apxPdfSigningService');const {fetchPdfBytes,pdfObjectKey}=require('./dist/src/services/apx/apxPdfAsset');const {uploadApxPdf}=require('./dist/src/services/apx/apxPdfUploadService');const live={id:row.classRowId,rawLink:row.noteRawLink,encrypted:row.encrypted,encryptionKey:row.encryptionKey,encryptionVersion:row.encryptionVersion};const signed=await signPdfLink(row.noteRawLink,'472');const bytes=await fetchPdfBytes(live,signed,'472');const asset=await uploadApxPdf(bytes,pdfObjectKey(ak));await Pdf.updateOne({_id:p._id,'pdfAsset.key':{$exists:false}},{$set:{pdfAsset:asset}});p=await Pdf.findById(p._id).lean();if(!p.pdfAsset?.key)throw Error('Repair failed');}
const head=await storage.headObject({bucket:cfg.bucket,key:p.pdfAsset.key});if(!head)throw Error('Stored object missing');
const prefix=await storage.getObjectRange({bucket:cfg.bucket,key:p.pdfAsset.key,start:0,end:4});if(Buffer.from(prefix).toString()!=='%PDF-')throw Error('Stored PDF header invalid');
const fresh=await Class.findById(c._id).select('pdfAssignments').lean();const priority=Math.max(0,...(fresh.pdfAssignments||[]).map(a=>a.priority||0))+1;
await Class.updateOne({_id:c._id,'pdfAssignments.pdfId':{$ne:p._id}},{$push:{pdfAssignments:{pdfId:p._id,priority}},$addToSet:{pdfIds:p._id}});
await Class.updateOne({_id:c._id},{$addToSet:{pdfIds:p._id}});
const check=await Class.findById(c._id).select('pdfIds pdfAssignments').lean();if(!check.pdfIds.some(v=>String(v)===String(p._id))||!check.pdfAssignments.some(v=>String(v.pdfId)===String(p._id)))throw Error('Attachment verification failed');
success++;emit({event:'imported',sourceId:t.sourceId,classId:t.classId,pdfId:String(p._id),created:result.created,sizeBytes:p.pdfAsset.sizeBytes,storedHeaderVerified:true});
if(result.created)await new Promise(r=>setTimeout(r,1000));
}catch(e){failed++;emit({event:'failed',sourceId:t.sourceId,error:e.name,message:String(e.message).replace(/https?:\/\/\S+/g,'[url]')});if(e.name==='ApxSignerQuotaError')break;}}
emit({event:'summary',success,failed,total:plan.length});await m.disconnect();})().catch(e=>{emit({event:'fatal',error:e.name,message:String(e.message).replace(/https?:\/\/\S+/g,'[url]')});process.exit(1)});
